import { useState, useCallback, useEffect, useRef } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ConversationHistory } from './components/ConversationHistory';
import { StatusBar } from './components/StatusBar';
import { ResetDataButton } from './components/ResetDataButton';
import { Document, AppStatus, FeedbackRating, QAHistory } from '../shared/types';

type View = 'conversation' | 'document';

const headerButton = (active: boolean) => ({
  padding: '6px 14px',
  background: active ? '#533483' : '#0f3460',
  color: '#e0e0e0',
  border: '1px solid #1a1a4e',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '13px',
});

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [view, setView] = useState<View>('conversation');
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [ratings, setRatings] = useState<Record<string, FeedbackRating>>({});
  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
  const [askError, setAskError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  /** Result of documents.search for the current query; null while the query is blank (show all). */
  const [searchResults, setSearchResults] = useState<Document[] | null>(null);
  const searchSeq = useRef(0);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  /** Loads the persisted Q&A history and feedback ratings. */
  const refreshConversation = useCallback(async () => {
    try {
      const [items, feedback] = await Promise.all([
        window.knowledgeBase.qa.history(),
        window.knowledgeBase.feedback.list(),
      ]);
      setHistory(items);
      setRatings(Object.fromEntries(feedback.map(f => [f.answerId, f.rating])));
    } catch (err) {
      console.error('Failed to load conversation:', err);
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    refreshConversation();
  }, [refreshDocuments, refreshConversation]);

  // Re-run the search when the query or the document set changes. Only the latest request
  // may update the list, so a slow earlier response cannot overwrite a newer one.
  useEffect(() => {
    const seq = ++searchSeq.current;
    if (searchQuery.trim() === '') {
      setSearchResults(null);
      return;
    }
    window.knowledgeBase.documents.search(searchQuery).then(
      results => {
        if (seq === searchSeq.current) setSearchResults(results);
      },
      err => console.error('Document search failed:', err),
    );
  }, [searchQuery, documents]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleReset = useCallback(async () => {
    setSelectedDoc(null);
    setView('conversation');
    setAskError(null);
    setSearchQuery('');
    await Promise.all([refreshDocuments(), refreshConversation()]);
  }, [refreshDocuments, refreshConversation]);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
    setView('document');
  }, []);

  const handleClearHistory = useCallback(async () => {
    try {
      await window.knowledgeBase.qa.clearHistory();
    } catch (err) {
      console.error('Clear history failed:', err);
    }
    await refreshConversation();
  }, [refreshConversation]);

  const handleAskQuestion = useCallback(async (question: string) => {
    setView('conversation');
    setAskError(null);
    setPendingQuestion(question);
    try {
      await window.knowledgeBase.qa.ask(question);
      await refreshConversation();
      // Refresh status after Q&A
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Q&A failed:', err);
      setAskError('Could not answer that question. Please try again.');
    } finally {
      setPendingQuestion(null);
    }
  }, [refreshConversation]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button
            type="button"
            aria-pressed={view === 'conversation'}
            onClick={() => setView('conversation')}
            style={headerButton(view === 'conversation')}
          >
            Conversation
          </button>
          <button type="button" onClick={refreshDocuments} style={headerButton(false)}>
            Refresh
          </button>
          <ResetDataButton onReset={handleReset} />
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={searchResults ?? documents}
            totalCount={documents.length}
            query={searchQuery}
            onQueryChange={setSearchQuery}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: conversation (Q&A history) or document detail, above the question box */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          <div style={{ flex: 1, overflow: 'auto', padding: '20px' }}>
            {view === 'document' && selectedDoc ? (
              <DocumentDetail document={selectedDoc} />
            ) : (
              <ConversationHistory
                history={history}
                ratings={ratings}
                pendingQuestion={pendingQuestion}
                error={askError}
                onClearHistory={handleClearHistory}
              />
            )}
          </div>

          <QuestionPanel onAsk={handleAskQuestion} disabled={pendingQuestion !== null} />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
import { beforeAll, describe, expect, it, vi } from 'vitest';
import { IPC_CHANNELS } from '../src/shared/types';
import { registerIpcHandlers, Services } from '../src/main/ipc-handlers';
import { makeServices, quietLogs, tempDir } from './helpers';

// Capture what the preload exposes and what it invokes.
const exposed: Record<string, any> = {};
const invoke = vi.fn(async (..._args: unknown[]) => undefined);
vi.mock('electron', () => ({
  contextBridge: { exposeInMainWorld: (key: string, api: unknown) => { exposed[key] = api; } },
  ipcRenderer: { invoke: (...args: unknown[]) => invoke(...args) },
}));

beforeAll(async () => {
  await import('../src/preload/preload');
});

/** Fake ipcMain that records handlers so tests can call them like the renderer would. */
function fakeIpcMain() {
  const handlers = new Map<string, (...args: any[]) => any>();
  return {
    handlers,
    ipcMain: { handle: (channel: string, fn: (...args: any[]) => any) => handlers.set(channel, fn) } as any,
    call: (channel: string, ...args: unknown[]) => {
      const fn = handlers.get(channel);
      if (!fn) throw new Error(`No handler for ${channel}`);
      return fn({}, ...args);
    },
  };
}

function wire() {
  quietLogs();
  vi.spyOn(Math, 'random').mockReturnValue(0);
  const services = makeServices(tempDir());
  const ipc = fakeIpcMain();
  registerIpcHandlers(ipc.ipcMain, services as Services);
  return { ...ipc, services };
}

describe('preload bridge', () => {
  it('exposes feedback.submit and feedback.list on window.knowledgeBase', async () => {
    const kb = exposed.knowledgeBase;
    expect(typeof kb.feedback.submit).toBe('function');
    expect(typeof kb.feedback.list).toBe('function');
    await kb.feedback.submit('answer-1', 'up');
    expect(invoke).toHaveBeenLastCalledWith(IPC_CHANNELS.SUBMIT_FEEDBACK, 'answer-1', 'up');
    await kb.feedback.list();
    expect(invoke).toHaveBeenLastCalledWith(IPC_CHANNELS.LIST_FEEDBACK);
  });

  it('every channel the preload invokes has a main-process handler', async () => {
    const { handlers } = wire();
    invoke.mockClear();
    const kb = exposed.knowledgeBase;
    for (const group of Object.values(kb) as Array<Record<string, (...a: any[]) => unknown>>) {
      for (const fn of Object.values(group)) await fn('x', 'up');
    }
    const used = new Set(invoke.mock.calls.map(c => c[0] as string));
    for (const channel of used) expect(handlers.has(channel), channel).toBe(true);
  });
});

describe('app bridge', () => {
  it('exposes app.reset on the app:reset channel', async () => {
    const kb = exposed.knowledgeBase;
    expect(typeof kb.app.reset).toBe('function');
    await kb.app.reset();
    expect(invoke).toHaveBeenLastCalledWith(IPC_CHANNELS.RESET_ALL_DATA);
  });
});

describe('feedback over IPC', () => {
  it('ask returns an id that feedback:submit accepts and feedback:list returns', async () => {
    const { call } = wire();
    const answer = await call(IPC_CHANNELS.ASK_QUESTION, 'How does feedback work?');
    expect(typeof answer.id).toBe('string');
    await call(IPC_CHANNELS.SUBMIT_FEEDBACK, answer.id, 'up');
    expect(await call(IPC_CHANNELS.LIST_FEEDBACK)).toEqual([
      { answerId: answer.id, rating: 'up', timestamp: expect.any(String) },
    ]);
  });

  it('feedback:submit rejects a bad rating', async () => {
    const { call } = wire();
    const answer = await call(IPC_CHANNELS.ASK_QUESTION, 'q');
    await expect(call(IPC_CHANNELS.SUBMIT_FEEDBACK, answer.id, 'sideways')).rejects.toThrow(/rating/);
  });
});
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { afterEach, vi } from 'vitest';
import { PersistenceService } from '../src/services/persistence-service';
import { DocumentService } from '../src/services/document-service';
import { IndexingService } from '../src/services/indexing-service';
import { QaService } from '../src/services/qa-service';
import { FeedbackService } from '../src/services/feedback-service';

const tempDirs: string[] = [];

afterEach(() => {
  for (const dir of tempDirs.splice(0)) fs.rmSync(dir, { recursive: true, force: true });
  vi.restoreAllMocks();
});

export function tempDir(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-test-'));
  tempDirs.push(dir);
  return dir;
}

/** Builds the services the way main.ts does, on a data dir. A second call on the same dir simulates a restart. */
export function makeServices(dataDir: string) {
  const persistence = new PersistenceService(dataDir);
  const documentService = new DocumentService(persistence);
  const indexingService = new IndexingService(persistence);
  const qaService = new QaService(persistence, indexingService);
  const feedbackService = new FeedbackService(persistence, id => qaService.hasAnswer(id));
  return { persistence, documentService, indexingService, qaService, feedbackService };
}

export const SAMPLE_DOCS = path.resolve(__dirname, '..', 'data', 'sample-documents');

/** Silence structured logs in test output. */
export function quietLogs() {
  vi.spyOn(console, 'log').mockImplementation(() => {});
  vi.spyOn(console, 'warn').mockImplementation(() => {});
  vi.spyOn(console, 'error').mockImplementation(() => {});
}
#!/usr/bin/env bash
# Abre la app real y comprueba que la interfaz tenga acceso a la API (window.knowledgeBase).
# Es la verificación de capa 3 mínima: si falla, la app compila pero el usuario no puede hacer nada.
set -u
PORT="${1:-9350}"
DATA="$(mktemp -d)"
env -u NODE_OPTIONS npx electron . --remote-debugging-port="$PORT" --user-data-dir="$DATA" >/dev/null 2>&1 &
PID=$!
OUT=""
for i in $(seq 1 30); do
  OUT="$(node --experimental-websocket scripts/check-bridge.mjs "$PORT" 2>/dev/null)" && break
  sleep 1
done
kill "$PID" 2>/dev/null; rm -rf "$DATA"
echo "$OUT"
if echo "$OUT" | grep -q '"bridge": "object"'; then
  echo "PASS: the running app exposes window.knowledgeBase"
else
  echo "FAIL: the running app does not expose window.knowledgeBase"
  echo "WHY: the preload did not load, so every button in the UI is disconnected from the app"
  echo "FIX: run 'bash scripts/check-architecture.sh' and follow its preload instructions, rebuild, and run this script again"
  exit 1
fi
#!/usr/bin/env bash
#
# check-architecture.sh - Verify layer boundary constraints
#
# Checks that:
# 1. No Node.js core modules (fs, path, os, child_process) in renderer code
# 2. No Electron IPC imports in service code
# 3. No React imports in services or main process code
#
# Exit code 0 = all checks pass
# Exit code 1 = violations found

set -euo pipefail

VIOLATIONS=0

echo "=== Architecture Boundary Checks ==="
echo ""

# Check 1: No fs/path imports in renderer
echo "Checking renderer for Node.js core module imports..."
RENDERER_FILES=$(find src/renderer -name '*.ts' -o -name '*.tsx' 2>/dev/null || true)
if [ -n "$RENDERER_FILES" ]; then
  while IFS= read -r file; do
    if grep -qE "import.*\b(fs|path|os|child_process)\b" "$file" 2>/dev/null; then
      echo "  VIOLATION: $file imports Node.js core module"
      VIOLATIONS=$((VIOLATIONS + 1))
    fi
  done <<< "$RENDERER_FILES"
fi
if [ "$VIOLATIONS" -eq 0 ]; then
  echo "  PASS: No Node.js core imports in renderer"
fi
echo ""

# Check 2: No Electron IPC in services
echo "Checking services for Electron IPC imports..."
SERVICE_FILES=$(find src/services -name '*.ts' 2>/dev/null || true)
SVIO=0
if [ -n "$SERVICE_FILES" ]; then
  while IFS= read -r file; do
    if grep -qE "import.*from\s+['\"]electron['\"]" "$file" 2>/dev/null; then
      echo "  VIOLATION: $file imports from electron"
      VIOLATIONS=$((VIOLATIONS + 1))
      SVIO=$((SVIO + 1))
    fi
    if grep -qE "\bipcMain\b|\bipcRenderer\b|\bBrowserWindow\b" "$file" 2>/dev/null; then
      echo "  VIOLATION: $file uses Electron IPC"
      VIOLATIONS=$((VIOLATIONS + 1))
      SVIO=$((SVIO + 1))
    fi
  done <<< "$SERVICE_FILES"
fi
if [ "$SVIO" -eq 0 ]; then
  echo "  PASS: No Electron IPC in services"
fi
echo ""

# Check 3: No React imports in services or main
echo "Checking services and main for React imports..."
BACKEND_FILES=$(find src/services src/main -name '*.ts' 2>/dev/null || true)
RVIO=0
if [ -n "$BACKEND_FILES" ]; then
  while IFS= read -r file; do
    if grep -qE "import.*from\s+['\"]react['\"]" "$file" 2>/dev/null; then
      echo "  VIOLATION: $file imports React"
      VIOLATIONS=$((VIOLATIONS + 1))
      RVIO=$((RVIO + 1))
    fi
  done <<< "$BACKEND_FILES"
fi
if [ "$RVIO" -eq 0 ]; then
  echo "  PASS: No React imports in services/main"
fi
echo ""

# Check 4: the preload must not load local modules at runtime while the sandbox is on
echo "Checking preload for local requires under the sandbox..."
if [ -f dist/preload/preload.js ] && grep -qE "require\(['\"]\.\.?/" dist/preload/preload.js; then
  if ! grep -qE "sandbox:\s*false" src/main/main.ts 2>/dev/null; then
    echo "  VIOLATION: dist/preload/preload.js requires a local file while the sandbox is on"
    echo "  WHY: a sandboxed preload cannot load local modules, so window.knowledgeBase is undefined and the UI cannot reach the app"
    echo "  FIX: bundle the preload into a single file (for example with esbuild) or keep it free of local imports. Do not disable the sandbox."
    VIOLATIONS=$((VIOLATIONS + 1))
  fi
else
  echo "  PASS: preload has no local runtime requires (or is not built yet)"
fi
echo ""

# Summary
echo "=== Summary ==="
if [ "$VIOLATIONS" -gt 0 ]; then
  echo "FAIL: $VIOLATIONS violation(s) found"
  exit 1
else
  echo "PASS: All architecture boundary checks passed"
  exit 0
fi
import { beforeEach, describe, expect, it, vi } from 'vitest';
import * as path from 'path';
import { renderToStaticMarkup } from 'react-dom/server';
import { describeConfidence } from '../src/renderer/confidence';
import { ConversationHistory } from '../src/renderer/components/ConversationHistory';
import { QAHistory } from '../src/shared/types';
import { makeServices, quietLogs, SAMPLE_DOCS, tempDir } from './helpers';

beforeEach(() => {
  quietLogs();
  vi.spyOn(Math, 'random').mockReturnValue(0);
});

describe('describeConfidence', () => {
  it('maps scores to high / medium / low with a percentage', () => {
    expect(describeConfidence(0.85)).toMatchObject({ level: 'high', percent: 85, label: 'High confidence (85%)' });
    expect(describeConfidence(0.7).level).toBe('high');
    expect(describeConfidence(0.5)).toMatchObject({ level: 'medium', percent: 50 });
    expect(describeConfidence(0.3)).toMatchObject({ level: 'low', percent: 30 });
  });

  it('clamps out-of-range and non-numeric values', () => {
    expect(describeConfidence(1.7).percent).toBe(100);
    expect(describeConfidence(-1)).toMatchObject({ level: 'low', percent: 0 });
    expect(describeConfidence(NaN)).toMatchObject({ level: 'low', percent: 0 });
  });
});

describe('Q&A history for the conversation', () => {
  it('keeps every exchange with its citations, excerpt and confidence across a restart', async () => {
    const dir = tempDir();
    const s = makeServices(dir);
    s.documentService.importDocument(path.join(SAMPLE_DOCS, 'design-notes.md'));
    s.documentService.importDocument(path.join(SAMPLE_DOCS, 'retrieval-plan.md'));
    await s.indexingService.startIndexing();
    await s.qaService.ask('What is the architecture design?');
    await s.qaService.ask('How does retrieval work?');

    const history = makeServices(dir).qaService.getHistory();
    expect(history.map(h => h.question)).toEqual(['What is the architecture design?', 'How does retrieval work?']);
    for (const h of history) {
      expect(h.response.citations.length).toBeGreaterThan(0);
      for (const c of h.response.citations) {
        expect(c.excerpt.length).toBeGreaterThan(0);
        expect(typeof c.documentTitle).toBe('string');
      }
      expect(h.response.confidence).toBeGreaterThan(0);
    }
  });
});

const sampleHistory: QAHistory[] = [
  {
    question: 'What is the architecture?',
    response: {
      id: 'a1',
      answer: 'Layered.',
      confidence: 0.85,
      timestamp: '2026-11-15T10:00:00.000Z',
      citations: [{ documentId: 'd1', documentTitle: 'design-notes', chunkIndex: 0, excerpt: 'The system uses layers' }],
    },
  },
  {
    question: 'Anything about cats?',
    response: { id: 'a2', answer: 'No relevant documents.', confidence: 0.3, timestamp: '2026-11-15T10:01:00.000Z', citations: [] },
  },
];

describe('ConversationHistory component', () => {
  const html = renderToStaticMarkup(
    <ConversationHistory history={sampleHistory} ratings={{ a1: 'up' }} onClearHistory={() => {}} />,
  );

  it('renders every exchange: question and answer', () => {
    expect(html).toContain('What is the architecture?');
    expect(html).toContain('Layered.');
    expect(html).toContain('Anything about cats?');
    expect(html.match(/data-answer-id=/g)).toHaveLength(2);
  });

