/** Fake ipcMain that records handlers so tests can call them like the renderer would. */
function fakeIpcMain() {
  const handlers = new Map<string, (...args: any[]) => any>();
  return {
    handlers,
    ipcMain: { handle: (channel: string, fn: (...args: any[]) => any) => handlers.set(channel, fn) } as any,
    call: (channel: string, ...args: unknown[]) => {
      const fn = handlers.get(channel);
      if (!fn) throw new Error(`No handler for ${channel}`);
      return fn({}, ...args);
    },
  };
}

